// Enhanced Service Functions for Task Management
const createMaterialCollectionTask = async (operationData, currentUser, notes = '') => {
  try {
    // Check if task already exists for this operation
    const existingTaskQuery = query(
      collection(db, 'industrialTasks'),
      where('sourcePO', '==', operationData.poNumber),
      where('sourceOperation', '==', operationData.operation),
      where('sourceItemIndex', '==', operationData.itemIndex),
      where('taskType', '==', 'material_collection')
    );
    
    const existingTasks = await getDocs(existingTaskQuery);
    
    if (!existingTasks.empty) {
      console.log('Material collection task already exists for this operation');
      return { success: false, message: 'Task already exists' };
    }

    const taskData = {
      title: `Material Collection: ${MACHINE_OPERATIONS[operationData.operation]?.name || operationData.operation}`,
      description: `Collect completed materials from PO: ${operationData.poNumber}, Item: ${operationData.itemDescription}. ${notes ? `Notes: ${notes}` : ''}`,
      category: 'material-collection',
      department: 'logistics',
      taskType: 'material_collection',
      priority: 'high',
      pickupRequired: true,
      pickupStatus: 'pending',
      pickupHistory: [],
      collectionStatus: 'pending',
      collectionDetails: {
        vendorLocation: operationData.vendorLocation || '',
        contactPerson: operationData.contactPerson || '',
        contactPhone: operationData.contactPhone || '',
        scheduledDate: null,
        collectedDate: null,
        deliveredDate: null,
        transporter: '',
        vehicleNumber: '',
        driverInfo: '',
        notes: '',
        documents: [],
        photos: [],
        verification: {
          qualityCheck: false,
          quantityVerified: false,
          documentationComplete: false
        }
      },
      dueDate: new Date(Date.now() + 24 * 60 * 60 * 1000),
      estimatedTime: 45,
      status: 'pending',
      completed: false,
      progress: 0,
      sequence: [
        { step: 'Verify material completion documentation', completed: false, critical: true },
        { step: 'Coordinate with production team', completed: false, critical: true },
        { step: 'Schedule transportation', completed: false, critical: true },
        { step: 'Perform quality verification', completed: false, critical: true },
        { step: 'Complete material handover', completed: false, critical: true },
        { step: 'Update system records', completed: false, critical: false }
      ],
      sourcePO: operationData.poNumber || '',
      sourcePONumber: operationData.poNumber || '',
      sourceOperation: operationData.operation || '',
      sourceItemIndex: typeof operationData.itemIndex === 'number' ? operationData.itemIndex : 0,
      sourceItemDescription: operationData.itemDescription || '',
      sourceVendor: operationData.vendorId || '',
      sourceVendorName: operationData.vendorName || '',
      sourceQuantity: typeof operationData.completedQuantity === 'number' ? operationData.completedQuantity : operationData.quantity || 0,
      sourceUnit: operationData.unit || 'pcs',
      sourceSpecifications: operationData.specifications || '',
      sourceMaterial: operationData.material || '',
      sourceMaterialInfo: operationData.materialInfo || {},
      operationId: `${operationData.poId || ''}_${typeof operationData.itemIndex === 'number' ? operationData.itemIndex : 0}_${operationData.operation || ''}`,
      autoGenerated: true,
      autoGeneratedFrom: 'status_manager',
      createdAt: serverTimestamp(),
      updatedAt: serverTimestamp(),
      createdBy: {
        uid: currentUser?.uid || 'system',
        name: currentUser?.displayName || 'System Auto-Generator',
        email: currentUser?.email || 'system@company.com',
        role: 'system'
      },
      assignedTo: null,
      assignedTeam: 'logistics',
      tags: ['material-collection', 'auto-generated', 'post-processing'],
      metadata: {
        originalPOId: operationData.poId,
        completionTimestamp: operationData.completionTime || serverTimestamp(),
        materialStatus: 'ready_for_collection',
        qualityCheckRequired: true,
        riskLevel: 'medium'
      }
    };

    // Remove undefined values
    Object.keys(taskData).forEach((key) => {
      if (taskData[key] === undefined) delete taskData[key];
    });

    const docRef = await addDoc(collection(db, 'industrialTasks'), taskData);
    
    console.log('Material collection task created successfully:', docRef.id);
    return { 
      success: true, 
      message: 'Material collection task created successfully',
      taskId: docRef.id 
    };
  } catch (error) {
    console.error('Error creating material collection task:', error);
    throw error;
  }
};

const checkAndCreateMaterialTasks = async (completedOperations, currentUser) => {
  try {
    const creationResults = [];
    
    for (const operation of completedOperations) {
      try {
        // Only create tasks for operations that are materially completed
        if (operation.materialInfo?.status === 'completed' && operation.materialInfo.completedQuantity > 0) {
          const result = await createMaterialCollectionTask(operation, currentUser, 
            `Automatically generated for completed operation: ${operation.materialInfo.completedQuantity} units completed`
          );
          creationResults.push({
            operation: operation,
            result: result
          });
        }
      } catch (opError) {
        console.error(`Failed to create task for operation ${operation.poNumber}:`, opError);
        creationResults.push({
          operation: operation,
          result: { success: false, message: opError.message }
        });
      }
    }
    
    return creationResults;
  } catch (error) {
    console.error('Error in batch task creation:', error);
    throw error;
  }
};

// Enhanced Collection Status Management
const updateCollectionStatus = async (taskId, newStatus, collectionDetails = {}, currentUser) => {
  try {
    const taskRef = doc(db, 'industrialTasks', taskId);
    const updateData = {
      collectionStatus: newStatus,
      updatedAt: serverTimestamp(),
      'collectionDetails.updatedAt': serverTimestamp(),
      'collectionDetails.updatedBy': {
        uid: currentUser?.uid,
        name: currentUser?.displayName,
        email: currentUser?.email
      }
    };

    // Add collection-specific updates
    if (newStatus === 'scheduled' && collectionDetails.scheduledDate) {
      const sched = collectionDetails.scheduledDate instanceof Date
        ? collectionDetails.scheduledDate
        : new Date(collectionDetails.scheduledDate);
      updateData['collectionDetails.scheduledDate'] = sched;
    }
    if (newStatus === 'collected') {
      updateData['collectionDetails.collectedDate'] = serverTimestamp();
    }
    if (newStatus === 'delivered') {
      updateData['collectionDetails.deliveredDate'] = serverTimestamp();
    }

    // Update transporter details if provided
    if (collectionDetails.transporter) {
      updateData['collectionDetails.transporter'] = collectionDetails.transporter;
    }
    if (collectionDetails.vehicleNumber) {
      updateData['collectionDetails.vehicleNumber'] = collectionDetails.vehicleNumber;
    }
    if (collectionDetails.driverInfo) {
      updateData['collectionDetails.driverInfo'] = collectionDetails.driverInfo;
    }
    if (collectionDetails.notes) {
      updateData['collectionDetails.notes'] = collectionDetails.notes;
    }

    await updateDoc(taskRef, updateData);
    return true;
  } catch (error) {
    console.error('Error updating collection status:', error);
    throw error;
  }
};

