// Custom Hook for Completed Operations Monitoring
const useCompletedOperations = () => {
  const [completedOperations, setCompletedOperations] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [connectionStatus, setConnectionStatus] = useState('connected');
  const unsubscribeRef = useRef(null);

  const fetchCompletedOperations = useCallback(async () => {
    setLoading(true);
    setError(null);
    
    try {
      const poQuery = query(
        collection(db, 'purchaseOrders'),
        orderBy('updatedAt', 'desc')
      );
      
      const querySnapshot = await getDocs(poQuery);
      const completedOps = [];
      
      querySnapshot.forEach((doc) => {
        const poData = doc.data();
        const materialTracking = poData.materialTracking || {};
        
        // Extract completed operations from material tracking
        Object.entries(materialTracking).forEach(([operationKey, materialInfo]) => {
          if (materialInfo.status === 'completed' && materialInfo.completedQuantity > 0) {
            const [itemIndexStr, operation] = operationKey.split('_');
            const itemIndex = parseInt(itemIndexStr);
            const item = poData.items?.[itemIndex];
            
            if (item && item.operation === operation) {
              completedOps.push({
                id: `${doc.id}_${operationKey}`,
                poId: doc.id,
                poNumber: poData.poNumber,
                vendorId: poData.vendorId,
                vendorName: poData.vendorName,
                vendorLocation: poData.vendorLocation || 'Not specified',
                contactPerson: poData.contactPerson || 'Not specified',
                contactPhone: poData.contactPhone || 'Not specified',
                itemIndex,
                operation,
                itemDescription: item.description || `Item ${itemIndex + 1}`,
                quantity: item.quantity || 0,
                completedQuantity: materialInfo.completedQuantity,
                unit: item.unit || 'pcs',
                unitPrice: item.unitPrice || 0,
                specifications: item.specifications || '',
                material: item.material || '',
                materialInfo: materialInfo,
                completedAt: materialInfo.lastUpdated || poData.updatedAt,
                createdAt: poData.createdAt,
                totalValue: (item.quantity || 0) * (item.unitPrice || 0),
                completedValue: (materialInfo.completedQuantity || 0) * (item.unitPrice || 0)
              });
            }
          }
        });
      });
      
      setCompletedOperations(completedOps);
      setConnectionStatus('connected');
    } catch (err) {
      console.error('Failed to fetch completed operations:', err);
      setError(err.message);
      setConnectionStatus('error');
    } finally {
      setLoading(false);
    }
  }, []);

  // Real-time listener for completed operations
  useEffect(() => {
    const setupRealtimeListener = () => {
      try {
        if (unsubscribeRef.current) {
          unsubscribeRef.current();
        }

        const poQuery = query(
          collection(db, 'purchaseOrders'),
          orderBy('updatedAt', 'desc')
        );

        unsubscribeRef.current = onSnapshot(
          poQuery,
          (snapshot) => {
            setConnectionStatus('connected');
            
            const hasMaterialChanges = snapshot.docChanges().some(change => {
              if (change.type === 'added' || change.type === 'modified') {
                const poData = change.doc.data();
                return poData.materialTracking;
              }
              return false;
            });

            if (hasMaterialChanges) {
              fetchCompletedOperations();
            }
          },
          (error) => {
            console.error('Real-time completed operations listener error:', error);
            setConnectionStatus('error');
          }
        );
      } catch (error) {
        console.error('Error setting up real-time listener:', error);
        setConnectionStatus('error');
      }
    };

    setupRealtimeListener();
    return () => {
      if (unsubscribeRef.current) {
        unsubscribeRef.current();
      }
    };
  }, [fetchCompletedOperations]);

  useEffect(() => {
    fetchCompletedOperations();
  }, [fetchCompletedOperations]);

  const retryConnection = () => {
    setConnectionStatus('connecting');
    fetchCompletedOperations();
  };

  return {
    completedOperations,
    loading,
    error,
    connectionStatus,
    refetch: fetchCompletedOperations,
    retryConnection
  };
};

// Custom Hook for Task Management
const useTaskManager = () => {
  const [tasks, setTasks] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const unsubscribeRef = useRef(null);

  const fetchTasks = useCallback(async () => {
    setLoading(true);
    setError(null);
    
    try {
      const tasksQuery = query(
        collection(db, 'industrialTasks'),
        where('autoGeneratedFrom', '==', 'status_manager')
      );
      
      const querySnapshot = await getDocs(tasksQuery);
      const tasksList = [];
      
      querySnapshot.forEach((doc) => {
        tasksList.push({
          id: doc.id,
          ...doc.data()
        });
      });
      // Client-side sort by createdAt desc
      tasksList.sort((a, b) => {
        const aDate = a.createdAt?.toDate?.() ? a.createdAt.toDate() : (a.createdAt ? new Date(a.createdAt) : new Date(0));
        const bDate = b.createdAt?.toDate?.() ? b.createdAt.toDate() : (b.createdAt ? new Date(b.createdAt) : new Date(0));
        return bDate - aDate;
      });
      
      setTasks(tasksList);
    } catch (err) {
      console.error('Failed to fetch tasks:', err);
      setError(err.message);
    } finally {
      setLoading(false);
    }
  }, []);

  // Real-time listener for tasks
  useEffect(() => {
    const setupRealtimeListener = () => {
      try {
        if (unsubscribeRef.current) {
          unsubscribeRef.current();
        }

        const tasksQuery = query(
          collection(db, 'industrialTasks'),
          where('autoGeneratedFrom', '==', 'status_manager')
        );

        unsubscribeRef.current = onSnapshot(
          tasksQuery,
          (snapshot) => {
            const tasksList = [];
            snapshot.forEach((doc) => {
              tasksList.push({
                id: doc.id,
                ...doc.data()
              });
            });
            // Client-side sort by createdAt desc
            tasksList.sort((a, b) => {
              const aDate = a.createdAt?.toDate?.() ? a.createdAt.toDate() : (a.createdAt ? new Date(a.createdAt) : new Date(0));
              const bDate = b.createdAt?.toDate?.() ? b.createdAt.toDate() : (b.createdAt ? new Date(b.createdAt) : new Date(0));
              return bDate - aDate;
            });
            setTasks(tasksList);
          },
          (error) => {
            console.error('Real-time tasks listener error:', error);
            setError('Real-time updates disconnected');
          }
        );
      } catch (error) {
        console.error('Error setting up tasks listener:', error);
        setError(error.message);
      }
    };

    setupRealtimeListener();
    return () => {
      if (unsubscribeRef.current) {
        unsubscribeRef.current();
      }
    };
  }, []);

  useEffect(() => {
    fetchTasks();
  }, [fetchTasks]);

  const updateTaskStatus = async (taskId, newStatus, currentUser) => {
    try {
      const taskRef = doc(db, 'industrialTasks', taskId);
      const updateData = {
        status: newStatus,
        updatedAt: serverTimestamp(),
        ...(newStatus === 'completed' && { completed: true, progress: 100 }),
        ...(newStatus === 'in_progress' && { progress: 50 })
      };

      await updateDoc(taskRef, updateData);
      return true;
    } catch (error) {
      console.error('Error updating task status:', error);
      throw error;
    }
  };

  const updateTaskProgress = async (taskId, progress, currentUser) => {
    try {
      const taskRef = doc(db, 'industrialTasks', taskId);
      await updateDoc(taskRef, {
        progress: Math.min(100, Math.max(0, progress)),
        updatedAt: serverTimestamp()
      });
      return true;
    } catch (error) {
      console.error('Error updating task progress:', error);
      throw error;
    }
  };

  return {
    tasks,
    loading,
    error,
    refetch: fetchTasks,
    updateTaskStatus,
    updateTaskProgress
  };
};

